using namespace cg3::cgal::internal;

std::vector<std::vector<cg3::Point2d>> cells;
if (sites.empty())
    return cells;

VD vd;
for (const auto& p : sites)
    vd.insert(Point_2(p.x(), p.y()));

for (VD::Face_iterator fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
    if (fit->is_unbounded())
        continue; // skip unbounded cells

    std::vector<cg3::Point2d> cell;
    Ccb_halfedge_circulator ec_start = fit->ccb_halfedges_begin();
    if (ec_start == Ccb_halfedge_circulator())
        continue; // no edges

    Ccb_halfedge_circulator ec = ec_start;
    do {
        Halfedge_handle he = ec;
        Vertex_handle vh = he->source();
        if (!vd.is_infinite(vh)) {
            const Point_2& pt = vh->point();
            cell.emplace_back(pt.x(), pt.y());
        }
        ++ec;
    } while (ec != ec_start);

    cells.push_back(std::move(cell));
}
return cells;

